<template>
  <div class="local-account-menu"><button type="button" class="account-trigger" :aria-expanded="open" @click="open = !open"><PokemonPortrait :form-id="avatarId" :name="profile?.nickname || '我的账户'" /><span>{{ profile?.nickname || '我的账户' }}<small>本地账户</small></span><UiIcon name="chevron" /></button><div v-if="open" class="account-popover"><button type="button" @click="showSettings"><UiIcon name="settings" />账户设置</button><button type="button" @click="signOut"><UiIcon name="team" />切换账号</button><button type="button" @click="signOut"><UiIcon name="arrow" />退出登录</button></div></div>
  <Teleport to="body"><div v-if="settings" class="account-overlay" @click.self="closeSettings"><section class="account-settings" role="dialog" aria-modal="true" aria-labelledby="account-title" tabindex="-1" ref="dialog" @keydown.esc="closeSettings" @keydown.tab="trapFocus"><header><div><h1 id="account-title">账户设置</h1><p>管理本机账户与个人资料</p></div><button type="button" aria-label="关闭账户设置" :disabled="busy || !!recoveryCode" @click="closeSettings"><UiIcon name="close" /></button></header>
    <template v-if="recoveryCode"><h2>请保存新的恢复码</h2><p>密码已修改，旧恢复码和其他登录会话已失效。保存后重新登录。</p><code class="recovery-code">{{ recoveryCode }}</code><label class="account-check"><input v-model="codeSaved" type="checkbox" />我已保存新的恢复码</label><button class="account-primary" type="button" :disabled="!codeSaved" @click="signOut">返回登录</button></template>
    <template v-else><div class="account-tabs"><button type="button" :aria-pressed="tab === 'profile'" @click="tab = 'profile'">个人资料</button><button type="button" :aria-pressed="tab === 'security'" @click="tab = 'security'">账号安全</button></div>
      <form v-if="tab === 'profile' && profile" @submit.prevent="saveProfile"><div class="account-profile-grid"><div class="account-avatar-picker"><PokemonPortrait :form-id="avatarId" :name="profile.nickname" /><label>预设头像<select v-model="profile.avatar"><option value="squirtle">杰尼龟</option><option value="bulbasaur">妙蛙种子</option><option value="pikachu">皮卡丘</option></select></label></div><div><label>用户名<input :value="profile.username" disabled /></label><label>昵称<input v-model="profile.nickname" maxlength="24" required /></label></div></div><div class="account-info"><strong>数据存储于当前电脑</strong><p>聊天记录、队伍和收藏按账号分别保存，不会跨设备同步。</p></div><button class="account-primary" type="submit" :disabled="busy">保存修改</button></form>
      <div v-if="tab === 'security'"><form @submit.prevent="changePassword"><h2>修改登录密码</h2><label>当前密码<input v-model="currentPassword" type="password" autocomplete="current-password" required maxlength="72" /></label><label>新密码<input v-model="newPassword" type="password" autocomplete="new-password" required minlength="10" maxlength="72" /></label><label>确认新密码<input v-model="confirmation" type="password" autocomplete="new-password" required maxlength="72" /></label><p>修改后所有会话失效，并生成新的恢复码。</p><button class="account-primary" type="submit" :disabled="busy">修改密码</button></form></div>
      <div v-if="legacy?.eligible && (legacy.conversations || legacy.teams)" class="account-info"><h2>认领旧工作区数据</h2><p>发现 {{ legacy.conversations }} 条旧会话、{{ legacy.teams }} 支旧队伍。仅首次创建的本机账号可认领；认领后归入当前账号。</p><form @submit.prevent="claim"><label>确认当前密码<input v-model="claimPassword" type="password" autocomplete="current-password" required /></label><label class="account-check"><input v-model="claimConfirmed" type="checkbox" required />确认这些旧数据属于我</label><button type="submit" class="account-secondary" :disabled="busy || !claimConfirmed">认领旧数据</button></form></div>
    </template><p v-if="error" class="account-error" role="alert">{{ error }}</p><p v-if="notice" class="account-status" role="status">{{ notice }}</p>
  </section></div></Teleport>
</template>
<script setup>
import { ref, computed, onMounted, onBeforeUnmount, nextTick } from 'vue'
import { localAccountRequest, fetchAuthSession } from '@/api'
import { useAuthSession } from '@/composables/useAuthSession'
import PokemonPortrait from './PokemonPortrait.vue'
import UiIcon from './UiIcon.vue'
const { signOut }=useAuthSession()
const open=ref(false),settings=ref(false),profile=ref(null),legacy=ref(null),tab=ref('profile'),busy=ref(false),error=ref(''),notice=ref(''),dialog=ref(null)
const currentPassword=ref(''),newPassword=ref(''),confirmation=ref(''),recoveryCode=ref(''),codeSaved=ref(false),claimPassword=ref(''),claimConfirmed=ref(false)
const avatarId=computed(()=>({squirtle:7,bulbasaur:1,pikachu:25}[profile.value?.avatar] || 7))
let previousFocus=null
async function load(){try{profile.value=await localAccountRequest('profile',null,'GET')}catch{ /* Settings offers an explicit retry path. */ }}
onMounted(load)
onBeforeUnmount(()=>{currentPassword.value='';newPassword.value='';claimPassword.value='';recoveryCode.value=''})
async function showSettings(){previousFocus=document.activeElement;open.value=false;settings.value=true;error.value='';notice.value='';await nextTick();dialog.value?.focus();try{profile.value=await localAccountRequest('profile',null,'GET');legacy.value=await localAccountRequest('legacy-data',null,'GET')}catch(e){error.value=e.message}}
function closeSettings(){if(busy.value || recoveryCode.value)return;settings.value=false;currentPassword.value='';newPassword.value='';confirmation.value='';claimPassword.value='';previousFocus?.focus()}
function trapFocus(event){const nodes=dialog.value?.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),[tabindex="0"]');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey && (document.activeElement===first || document.activeElement===dialog.value)){event.preventDefault();last.focus()}else if(!event.shiftKey && document.activeElement===last){event.preventDefault();first.focus()}}
async function perform(action){busy.value=true;error.value='';notice.value='';try{await fetchAuthSession();await action()}catch(e){error.value=e.message}finally{busy.value=false}}
async function saveProfile(){await perform(async()=>{profile.value=await localAccountRequest('profile',{nickname:profile.value.nickname,avatar:profile.value.avatar},'PATCH');notice.value='个人资料已保存'})}
async function changePassword(){if(newPassword.value!==confirmation.value){error.value='两次新密码不一致';return}await perform(async()=>{const result=await localAccountRequest('password',{currentPassword:currentPassword.value,newPassword:newPassword.value});recoveryCode.value=result.recoveryCode});currentPassword.value='';newPassword.value='';confirmation.value=''}
async function claim(){await perform(async()=>{legacy.value=await localAccountRequest('legacy-data',{password:claimPassword.value});notice.value='旧数据已认领，关闭设置后刷新页面即可查看'});claimPassword.value='';claimConfirmed.value=false}
</script>
